create table public.data_catalog (
 id text primary key check (id ~ '^[a-z0-9][a-z0-9_-]{1,100}$'),
 call_id uuid not null references public.calls(id),
 name text not null check (length(name) between 1 and 200),
 source_path text not null check (source_path ~ '^/cbi/data/[^?#]+\.csv$' and source_path not like '%..%'),
 metadata jsonb not null default '{}' check (jsonb_typeof(metadata)='object'),
 active_version uuid,
 created_at timestamptz not null default now()
);
create table public.data_versions (
 id uuid primary key default gen_random_uuid(),
 dataset_id text not null references public.data_catalog(id),
 csv_text text not null check (octet_length(csv_text) between 1 and 10000000),
 settings jsonb not null default '{}' check (jsonb_typeof(settings)='object'),
 note text not null check (length(trim(note)) between 1 and 2000),
 content_hash text generated always as (md5(csv_text)) stored,
 created_by uuid not null default auth.uid() references public.profiles(id),
 created_at timestamptz not null default now(),
 unique(dataset_id,id)
);
alter table public.data_catalog add constraint data_catalog_active_version_fk foreign key(id,active_version) references public.data_versions(dataset_id,id);
create index data_catalog_call_idx on public.data_catalog(call_id);
create index data_versions_dataset_time_idx on public.data_versions(dataset_id,created_at desc);
create index data_versions_author_idx on public.data_versions(created_by);
alter table public.data_catalog enable row level security;
alter table public.data_versions enable row level security;
revoke all on public.data_catalog,public.data_versions from anon,authenticated;
grant select,insert,update on public.data_catalog to authenticated;
grant select,insert on public.data_versions to authenticated;
create policy data_catalog_read on public.data_catalog for select to authenticated using (
 (select private.current_user_is_admin()) or ((select private.current_user_is_active()) and exists(select 1 from public.calls c where c.id=call_id))
);
create policy data_catalog_create on public.data_catalog for insert to authenticated with check ((select private.current_user_is_admin()));
create policy data_catalog_update on public.data_catalog for update to authenticated using ((select private.current_user_is_admin())) with check ((select private.current_user_is_admin()));
create policy data_versions_read on public.data_versions for select to authenticated using (exists(select 1 from public.data_catalog c where c.id=dataset_id));
create policy data_versions_create on public.data_versions for insert to authenticated with check ((select private.current_user_is_admin()) and created_by=(select auth.uid()));
